  "inlineSchema": "generator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// TENANCY / ORGANIZATION\nmodel Tenant {\n  id        String    @id @default(cuid())\n  name      String\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  outlets       Outlet[]\n  users         User[]\n  settings      TenantSetting[]\n  menuTemplates MenuTemplate[]\n}\n\n// OUTLETS (locations)\nmodel Outlet {\n  id        String    @id @default(cuid())\n  name      String\n  tenantId  String\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n  deletedAt DateTime?\n\n  tenant          Tenant                     @relation(fields: [tenantId], references: [id])\n  users           User[]\n  floors          Floor[]\n  menuCategories  MenuCategory[]\n  orders          Order[]\n  deliveryConfigs DeliveryAggregatorConfig[]\n  ingredients     Ingredient[]\n  inventories     Inventory[]\n  journalEntries  JournalEntry[]\n  menuItems       OutletMenuItem[]\n  inventory       OutletInventory[]\n  shifts          Shift[]\n}\n\n// USERS (tenant-scoped; tenantId nullable for platform SUPERADMIN)\nmodel User {\n  id        String   @id @default(cuid())\n  tenantId  String?\n  outletId  String? // For staff/managers assigned to a specific outlet\n  name      String\n  email     String   @unique\n  password  String\n  role      Role     @default(STAFF)\n  isActive  Boolean  @default(true) // For deactivating users\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n\n  tenant Tenant? @relation(fields: [tenantId], references: [id])\n  outlet Outlet? @relation(fields: [outletId], references: [id])\n  shifts Shift[]\n}\n\nenum Role {\n  SUPERADMIN\n  OWNER\n  MANAGER\n  STAFF\n}\n\n// FLOORS & TABLE SETUP\nmodel Floor {\n  id       String @id @default(cuid())\n  outletId String\n  name     String\n\n  outlet Outlet  @relation(fields: [outletId], references: [id])\n  tables Table[]\n}\n\nmodel Table {\n  id      String @id @default(cuid())\n  name    String\n  seats   Int    @default(4)\n  floorId String\n\n  floor  Floor   @relation(fields: [floorId], references: [id])\n  orders Order[]\n}\n\n// MENU\nmodel MenuCategory {\n  id       String @id @default(cuid())\n  outletId String\n  name     String\n\n  outlet Outlet     @relation(fields: [outletId], references: [id])\n  items  MenuItem[]\n}\n\nmodel MenuItem {\n  id          String  @id @default(cuid())\n  categoryId  String\n  name        String\n  description String?\n  price       Float\n  imageUrl    String?\n  isAvailable Boolean @default(true)\n\n  category        MenuCategory         @relation(fields: [categoryId], references: [id])\n  variants        MenuVariant[]\n  ingredients     MenuItemIngredient[]\n  orderItems      OrderItem[]\n  outletMenuItems OutletMenuItem[]\n}\n\nmodel MenuVariant {\n  id         String @id @default(cuid())\n  menuItemId String\n  name       String\n  price      Float\n\n  menuItem   MenuItem    @relation(fields: [menuItemId], references: [id])\n  orderItems OrderItem[]\n}\n\n// TENANT SETTINGS\nmodel TenantSetting {\n  id       String @id @default(cuid())\n  tenantId String\n  key      String\n  value    String\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n\n  @@unique([tenantId, key])\n}\n\n// MENU TEMPLATES (tenant-scoped)\nmodel MenuTemplate {\n  id       String @id @default(cuid())\n  tenantId String\n  name     String\n\n  tenant Tenant @relation(fields: [tenantId], references: [id])\n  // Define relation to menu items if needed\n}\n\n// INGREDIENTS & INVENTORY\nmodel Ingredient {\n  id       String @id @default(cuid())\n  outletId String\n  name     String\n  unit     String // kg, g, L, ml\n  cost     Float\n\n  outlet            Outlet               @relation(fields: [outletId], references: [id])\n  menuItems         MenuItemIngredient[]\n  inventories       Inventory[]\n  outletInventories OutletInventory[]\n}\n\nmodel MenuItemIngredient {\n  id           String @id @default(cuid())\n  menuItemId   String\n  ingredientId String\n  quantity     Float // e.g. 0.05 kg\n\n  menuItem   MenuItem   @relation(fields: [menuItemId], references: [id])\n  ingredient Ingredient @relation(fields: [ingredientId], references: [id])\n}\n\nmodel Inventory {\n  id           String   @id @default(cuid())\n  outletId     String\n  ingredientId String\n  quantity     Float // current stock\n  updatedAt    DateTime @updatedAt\n\n  outlet     Outlet     @relation(fields: [outletId], references: [id])\n  ingredient Ingredient @relation(fields: [ingredientId], references: [id])\n}\n\n// OUTLET-SPECIFIC MENU OVERRIDES\nmodel OutletMenuItem {\n  id          String   @id @default(cuid())\n  outletId    String\n  menuItemId  String\n  price       Float?\n  isAvailable Boolean?\n\n  outlet   Outlet   @relation(fields: [outletId], references: [id])\n  menuItem MenuItem @relation(fields: [menuItemId], references: [id])\n\n  @@unique([outletId, menuItemId])\n}\n\n//\n// ORDERS\nmodel Order {\n  id           String      @id @default(cuid())\n  tenantId     String\n  outletId     String\n  tableId      String?\n  type         OrderType   @default(DINE_IN)\n  status       OrderStatus @default(PENDING)\n  subtotal     Float       @default(0)\n  finalTotal   Float       @default(0)\n  customerName String?\n  createdAt    DateTime    @default(now())\n  updatedAt    DateTime    @updatedAt\n\n  outlet Outlet      @relation(fields: [outletId], references: [id])\n  table  Table?      @relation(fields: [tableId], references: [id])\n  items  OrderItem[]\n}\n\nmodel OrderItem {\n  id         String  @id @default(cuid())\n  orderId    String\n  menuItemId String\n  variantId  String?\n  quantity   Int\n  price      Float\n\n  order    Order        @relation(fields: [orderId], references: [id])\n  menuItem MenuItem     @relation(fields: [menuItemId], references: [id])\n  variant  MenuVariant? @relation(fields: [variantId], references: [id])\n}\n\nenum OrderType {\n  DINE_IN\n  TAKEAWAY\n  DELIVERY\n}\n\nenum OrderStatus {\n  PENDING\n  IN_PROGRESS\n  COMPLETED\n  CANCELLED\n}\n\n// DELIVERY CONFIG\nmodel DeliveryAggregatorConfig {\n  id       String  @id @default(cuid())\n  outletId String\n  name     String // Talabat, Careem, Noon\n  apiKey   String?\n  isActive Boolean @default(true)\n\n  outlet Outlet @relation(fields: [outletId], references: [id])\n}\n\n// ACCOUNTING / JOURNAL\nmodel JournalEntry {\n  id          String   @id @default(cuid())\n  outletId    String\n  description String\n  amount      Float\n  createdAt   DateTime @default(now())\n\n  outlet Outlet @relation(fields: [outletId], references: [id])\n}\n\n// OUTLET INVENTORY (physical counts per outlet)\nmodel OutletInventory {\n  id           String   @id @default(cuid())\n  outletId     String\n  ingredientId String\n  quantity     Float\n  createdAt    DateTime @default(now())\n  updatedAt    DateTime @updatedAt\n\n  outlet     Outlet     @relation(fields: [outletId], references: [id])\n  ingredient Ingredient @relation(fields: [ingredientId], references: [id])\n}\n\n// SHIFTS (cash/shift management)\nmodel Shift {\n  id        String    @id @default(cuid())\n  outletId  String\n  userId    String\n  startAt   DateTime  @default(now())\n  endAt     DateTime?\n  startCash Float\n  endCash   Float?\n\n  outlet Outlet @relation(fields: [outletId], references: [id])\n  user   User   @relation(fields: [userId], references: [id])\n}\n\n// CUSTOMERS\nmodel Customer {\n  id        String   @id @default(cuid())\n  name      String\n  phone     String?\n  email     String?\n  createdAt DateTime @default(now())\n  updatedAt DateTime @updatedAt\n}\n",
